# frozen_string_literal: true

require_relative "test_helper"

# Pull in frontend + codegen modules.
require "runar_compiler/frontend/ast_nodes"
require "runar_compiler/frontend/diagnostic"
require "runar_compiler/frontend/validator"
require "runar_compiler/frontend/typecheck"
require "runar_compiler/frontend/anf_lower"
require "runar_compiler/frontend/parser_ts"
require "runar_compiler/codegen/stack"

# Tests that `deserialize_state` codegen supports the full set of
# property types the validator allows (the 14-type VALID_PROP_TYPES
# allowlist in frontend/validator.rb) and emits the CORRECT bytes for
# each, not merely "some bytes that happen to compile".
#
# F-333 (CL-GAP-050): the original version of this file had only 7 of
# the 14 types, and every assertion was `script.length > 0` /
# `contract_name == ...` — compile-only checks that cannot tell the
# three deserialize_state codegen shapes apart:
#   1. fixed-width NUMERIC  (bigint/boolean/RabinSig/RabinPubKey):
#      OP_SPLIT then OP_BIN2NUM
#   2. fixed-width BYTE-STRING (PubKey/Addr/Ripemd160/Sha256/Point/
#      P256Point/P384Point): OP_SPLIT only, no OP_BIN2NUM
#   3. VARIABLE-LENGTH (ByteString/Sig/SigHashPreimage): push-data
#      decode, no fixed OP_SPLIT at all
# A contract that routes a type through the WRONG shape, or uses the
# wrong fixed width, still compiles cleanly (the stack balances either
# way) and produces a non-empty script with the right contract_name —
# so the old tests passed on broken codegen. See
# remediation-logs/F-333/ for mutation-testing evidence: 3 single-line
# mutations to the codegen (one per shape) left all 7 original tests
# green while every byte-exact assertion below went red for exactly
# the mutated type.
#
# Each test below compiles the SAME single-mutable-property contract
# shape the TypeScript reference compiler was fed, and asserts the
# emitted script hex is byte-IDENTICAL to the TypeScript tier's output
# for that type (`TS_REFERENCE_HEX`, generated once via
# `packages/runar-compiler`'s `compile()` with
# `disableConstantFolding: true` — the same flag this file's Ruby
# helper passes — see remediation-logs/F-333/gen_ref_ts.txt for the
# exact generator and remediation-logs/F-333/ts_reference_hex.txt /
# ruby_hex_at_head.txt for the side-by-side values this was diffed
# against at HEAD). Any future change to the Ruby deserialize_state
# codegen that moves these bytes for ANY of the 14 types will turn one
# of these tests red.
#
# This mirrors the Rust compiler fix in commit e879e58 and extends the
# Ruby codegen test coverage to the full 14-type allowlist.
class TestDeserializeStateTypes < Minitest::Test
  # Golden bytes from the TypeScript reference compiler
  # (packages/runar-compiler) for the exact same source shape as
  # `compile_stateful_with_type` below, one mutable property of each
  # VALID_PROP_TYPES type, compiled with constant folding disabled.
  TS_REFERENCE_HEX = {
    "bigint" => "",
    "boolean" => "",
    "ByteString" => "",
    "PubKey" => "",
    "Sig" => "",
    "Sha256" => "",
    "Ripemd160" => "",
    "Addr" => "",
    "SigHashPreimage" => "",
    "RabinSig" => "",
    "RabinPubKey" => "",
    "Point" => "",
    "P256Point" => "",
    "P384Point" => "",
  }.freeze

  # Compile a stateful contract with a single mutable property of the
  # given TS type. Returns the artifact on success, raises on failure.
  def compile_stateful_with_type(ts_type, contract_name)
    source = <<~TS
      import { StatefulSmartContract, #{ts_type} } from 'runar-lang';

      class #{contract_name} extends StatefulSmartContract {
        value: #{ts_type};

        constructor(value: #{ts_type}) {
          super(value);
          this.value = value;
        }

        public update(newValue: #{ts_type}): void {
          this.value = newValue;
        }
      }
    TS

    parse_result = RunarCompiler.send(:_parse_source, source, "#{contract_name}.runar.ts")
    assert_empty parse_result.errors.map(&:format_message), "unexpected parse errors"
    refute_nil parse_result.contract

    val_result = RunarCompiler::Frontend.validate(parse_result.contract)
    assert_empty val_result.errors.map(&:format_message), "unexpected validation errors"

    tc_result = RunarCompiler::Frontend.type_check(parse_result.contract)
    assert_empty tc_result.errors.map(&:format_message), "unexpected type check errors"

    program = RunarCompiler::Frontend.lower_to_anf(parse_result.contract)
    RunarCompiler.compile_from_program(program, disable_constant_folding: true)
  end

  # Compile with the given type and assert the emitted script is
  # byte-identical to the TypeScript reference compiler's output for
  # the same contract shape. This is the assertion the old
  # compile-only tests could not make: two different codegen shapes
  # (or two different fixed widths) can both yield a non-empty,
  # correctly-named script while disagreeing on the actual bytes.
  def assert_deserialize_state_matches_ts(ts_type, contract_name)
    artifact = compile_stateful_with_type(ts_type, contract_name)
    refute_nil artifact
    assert artifact.script.length > 0, "#{ts_type} contract should have non-empty script"
    assert_equal contract_name, artifact.contract_name
    assert_equal TS_REFERENCE_HEX.fetch(ts_type), artifact.script,
                 "#{ts_type}: Ruby deserialize_state codegen diverged from the TS reference"
  end

  # ---------------------------------------------------------------------------
  # Fixed-width NUMERIC subtypes (OP_SPLIT + OP_BIN2NUM)
  # ---------------------------------------------------------------------------

  def test_deserialize_state_bigint_codegens_cleanly
    assert_deserialize_state_matches_ts("bigint", "TagBigint")
  end

  def test_deserialize_state_boolean_codegens_cleanly
    assert_deserialize_state_matches_ts("boolean", "TagBool")
  end

  def test_deserialize_state_rabin_sig_codegens_cleanly
    assert_deserialize_state_matches_ts("RabinSig", "TagRSig")
  end

  def test_deserialize_state_rabin_pubkey_codegens_cleanly
    assert_deserialize_state_matches_ts("RabinPubKey", "TagRPk")
  end

  # ---------------------------------------------------------------------------
  # Fixed-width BYTE-STRING subtypes (OP_SPLIT only, no OP_BIN2NUM)
  # ---------------------------------------------------------------------------

  def test_deserialize_state_pubkey_codegens_cleanly
    assert_deserialize_state_matches_ts("PubKey", "TagPubKey")
  end

  def test_deserialize_state_addr_codegens_cleanly
    assert_deserialize_state_matches_ts("Addr", "TagAddr")
  end

  def test_deserialize_state_sha256_codegens_cleanly
    assert_deserialize_state_matches_ts("Sha256", "TagSha256")
  end

  def test_deserialize_state_ripemd160_codegens_cleanly
    assert_deserialize_state_matches_ts("Ripemd160", "TagR160")
  end

  def test_deserialize_state_point_codegens_cleanly
    assert_deserialize_state_matches_ts("Point", "TagPoint")
  end

  def test_deserialize_state_p256point_codegens_cleanly
    assert_deserialize_state_matches_ts("P256Point", "TagP256")
  end

  def test_deserialize_state_p384point_codegens_cleanly
    assert_deserialize_state_matches_ts("P384Point", "TagP384")
  end

  # ---------------------------------------------------------------------------
  # Variable-length subtypes — must use push-data-decode path,
  # not a fixed OP_SPLIT.
  # ---------------------------------------------------------------------------

  def test_deserialize_state_bytestring_codegens_cleanly
    assert_deserialize_state_matches_ts("ByteString", "TagBytes")
  end

  def test_deserialize_state_sig_codegens_cleanly
    assert_deserialize_state_matches_ts("Sig", "TagSig")
  end

  def test_deserialize_state_sighash_preimage_codegens_cleanly
    assert_deserialize_state_matches_ts("SigHashPreimage", "TagShp")
  end
end
